/// If the file name of the given path has an ignored suffix, return a new
/// path with that suffix removed.
pub fn strip_suffix_from_path(&self, path: &Path) -> Option<PathBuf> {
    let file_name = path.file_name()?.to_str()?;
    let stripped_file_name = self
        .values
        .iter()
        .find_map(|suffix| file_name.strip_suffix(suffix))?;
    Some(path.with_file_name(stripped_file_name))
}

